  await run("(()=>{const id=document.querySelector('.player-mat[data-seat=\"1\"] .hand .card').dataset.card;for(const selector of ['.player-mat[data-seat=\"0\"] .battlefield .cards','.player-mat[data-seat=\"0\"] .hand','#stack','.player-mat[data-seat=\"0\"] .pile.graveyard']){const data=new DataTransfer();data.setData('application/x-commander-card',id);document.querySelector(selector).dispatchEvent(new DragEvent('drop',{bubbles:true,cancelable:true,shiftKey:true,dataTransfer:data}));}})()");assert.equal(await run("localStorage.getItem('commanderLab')"),beforePerspective,'Direct drops must not bypass the opponent-hand lock');
